-- Seed 4 real, independently web-researched CINEMA candidates for admin
-- review (2026-10-12, direct user request right after the INDEPENDENT
-- CINEMA -> CINEMA rename: "but seed some cinemas too"). All 5 existing
-- live cinemas (Everyman, Savoy, HOME, Rex, Cinemac) sit only in
-- Manchester/Cheshire; these diversify coverage into districts the
-- catalog had expanded into with no cinema representation at all
-- (Chelsea, Notting Hill, Stockport Underbanks, Chester).
--
-- Each was verified via live web search the same day, not recalled from
-- training data, specifically to avoid seeding a stale or closed venue
-- (Curzon Mayfair was researched and deliberately dropped from this list
-- for exactly that reason — its lease/redevelopment status as of today
-- is genuinely unclear, possibly closed). Gate 1 reasoning and a proposed
-- distinctiveness score are filled in (unlike the raw daily-pipeline
-- candidates in 0041/0044, which arrive unreviewed) since real research
-- was already done; still landed as 'pending_review', not promoted
-- directly to the live venues table, since these are brand-new additions
-- the admin hasn't signed off on yet.

insert into venue_candidates (
  name, type, sub_preference_tags, spend_level, district_id, metro,
  lat, lon, pet_friendly, dietary_options, photos, description, bands, base,
  gate1_reasoning, distinctiveness_proposed, distinctiveness_reasoning,
  ownership, ownership_evidence, sources, status, coordinate_method
) values
  ('Everyman Chelsea', 'CINEMA', '{}', 3, 'chelsea', 'london', 51.485345, -0.173628, false, '{none}', '{}', 'Three screens on King''s Road, luxury sofas and armchairs, and a bar that brings cocktails and sharing plates to your seat before the trailers.', '{"afternoon","evening"}', 82, 'Same Everyman chain already live in the catalog (Everyman Cinema, Altrincham) — comfortable, well-run, luxury-seat cinema with table service; a Curia member would be entirely at home. Opened 2020 on the site of a demolished four-screen Cineworld, the premium replacement for exactly the kind of mass-market multiplex Gate 1 exists to keep out.', 4, 'Matches the distinctiveness already assigned to the sibling Everyman Cinema (Altrincham) entry for brand consistency.', 'independent', '{"note":"Everyman Media Group. Matches the ownership classification already applied to the live Everyman Cinema (Altrincham) entry for brand consistency."}'::jsonb, '[{"note":"Researched via live web search 2026-10-12, confirmed currently operating. Added at user request to diversify CINEMA category coverage beyond the existing 5 Manchester/Cheshire-only venues, following the INDEPENDENT CINEMA -> CINEMA rename. Address: 279 King''s Road, London SW3 5EW."}]'::jsonb, 'pending_review', 'Geocoded postcode (SW3 5EW) via postcodes.io'),
  ('The Plaza', 'CINEMA', '{}', 2, 'stockport-underbanks', 'manchester', 53.409241, -2.161371, false, '{none}', '{}', 'Grade II* art deco super cinema on Mersey Square, saved from demolition by a community campaign and restored seat-by-seat to its 1932 glamour — a working cinema and theatre run by a volunteer trust, the original organ still in the pit.', '{"afternoon","evening"}', 75, 'A heritage-listed cinema and theatre run entirely by a volunteer charitable trust, genuinely singular rather than a commercial operation at all — clears Gate 1 easily on craft and care alone, the opposite end of the spectrum from a mass-market multiplex.', 5, 'Grade II* listed, one of a kind — no comparable venue exists elsewhere in the catalog or realistically could.', 'independent', '{"note":"Run by the Stockport Plaza Trust, a registered charity formed after a community campaign and a 550k-pound council-backed purchase prevented demolition; restored in 2010 via a 2m-pound Heritage Lottery Fund grant plus matched funding. Not a commercial chain of any kind."}'::jsonb, '[{"note":"Researched via live web search 2026-10-12, confirmed currently operating as a cinema and theatre. Added at user request to diversify CINEMA category coverage. Address: Mersey Square, Stockport SK1 1SP."}]'::jsonb, 'pending_review', 'Geocoded postcode (SK1 1SP) via postcodes.io'),
  ('Storyhouse', 'CINEMA', '{}', 2, 'chester', 'cheshire', 53.192281, -2.893619, false, '{none}', '{}', 'Chester''s Grade II-listed 1936 Odeon, empty for a decade, reborn in 2017 as a 100-seat boutique screen on a mezzanine above a library, theatre and bar — the same building, the opposite of what it used to be.', '{"afternoon","evening"}', 76, 'An independent charitable trust''s boutique screen inside a converted civic building, cinema, theatre, library and bar sharing one space — the same shape as the HOME (Deansgate) precedent already live in the catalog. Genuinely the opposite of the mass-market Odeon that used to occupy this exact building.', 4, 'Directly comparable to HOME (Deansgate), already live at distinctiveness 4 — a combined cultural space, not a plain screen.', 'independent', '{"note":"Operated by Storyhouse, an independent registered charity, not a cinema chain."}'::jsonb, '[{"note":"Researched via live web search 2026-10-12, confirmed currently operating. Added at user request to diversify CINEMA category coverage. Address: Hunter Street, Chester CH1 2AR."}]'::jsonb, 'pending_review', 'Geocoded postcode (CH1 2AR) via postcodes.io'),
  ('Electric Cinema', 'CINEMA', '{}', 4, 'notting-hill', 'london', 51.515524, -0.205066, false, '{none}', '{}', 'One of Britain''s oldest working cinemas, on Portobello Road since 1910 — leather armchairs, two rear sofas, six double beds in the front row, and a waiter who brings the cocktails to your seat before the lights go down.', '{"afternoon","evening"}', 88, 'Soho House-operated, genuinely singular — double beds, table service, one of the oldest working cinemas in Britain. About as far from a mass-market multiplex as the category gets; a Curia member would already know the name.', 5, 'No comparable venue in the existing catalog — a genuinely singular format and history, not just a well-run standard cinema.', 'small_group', '{"note":"Operated by Soho House Group (the members''-club hospitality company) as a standalone heritage cinema, not part of any cinema chain — closer in kind to how Soho House runs its member clubs than to a multiplex operator."}'::jsonb, '[{"note":"Researched via live web search 2026-10-12, confirmed currently operating. Added at user request to diversify CINEMA category coverage. Address: 191 Portobello Road, London W11 2ED."}]'::jsonb, 'pending_review', 'Geocoded postcode (W11 2ED) via postcodes.io');
